List<Map> _list(Map d,List<String> keys){for(final k in keys){final v=d[k];if(v is List)return v.whereType<Map>().toList();}return [];}List<Map> _statementRows(Map d,List<String> keys){final out=<Map>[];void add(dynamic v){if(v is List){out.addAll(v.whereType<Map>());}else if(v is Map){if(v['lines'] is List)out.addAll((v['lines'] as List).whereType<Map>());if(v['accounts'] is List)out.addAll((v['accounts'] as List).whereType<Map>());for(final e in v.values){if(e is Map||e is List)add(e);}}} for(final k in keys){if(d.containsKey(k))add(d[k]);} return out;}
