String _period(String a,String b)=>a.trim().isEmpty?'As of $b':'$a to $b';bool _balanced(Map d,Object? diff){final v=d['balanced']??d['is_balanced'];if(v is bool)return v;return toCents(diff)==0;}
Widget _statusChip(String label,Object? v){final ok=v==true||v.toString().toLowerCase().contains('balanced');return Chip(avatar:Icon(ok?Icons.check_circle:Icons.warning,color:ok?Colors.green:Colors.orange),label:Text('$label: ${ok?'Balanced':'Out of Balance'}'));}
