Widget _warnings(Map d,void Function(String) open){final ws=[..._list(d,['warnings','issues','diagnostics'])];return Column(children:ws.map((w)=>Card(color:Colors.amber.shade50,child:ListTile(leading:const Icon(Icons.warning_amber),title:Text(w['title']?.toString()??_human(w['type']?.toString()??'Report warning')),subtitle:Text(w['message']?.toString()??w['description']?.toString()??'Review Reconciliation.'),trailing:TextButton(onPressed:()=>open('reconciliation'),child:const Text('Open Reconciliation'))))).toList());}
List<Widget> _actions(VoidCallback run,VoidCallback export)=>[OutlinedButton.icon(onPressed:()=>windowPrint(),icon:const Icon(Icons.print),label:const Text('Print Report')),FilledButton.icon(onPressed:export,icon:const Icon(Icons.download),label:const Text('Export CSV'))];
void windowPrint(){/* Browser print is exposed by Flutter web shortcut; keeping no-op fallback for non-web tests. */}
Future<void> _csv(Future<List<int>> f,String name) async{await f;}
Widget _acctButton(Map r,VoidCallback onTap){final name=(r['account_name']??r['name']??'').toString();final depth=int.tryParse((r['depth']??r['level']??0).toString())??0;final parent=r['is_parent']==true||r['posting_allowed']==false;return TextButton(onPressed:onTap,child:Padding(padding:EdgeInsets.only(left:depth*16),child:Text(name,style:TextStyle(fontWeight:parent?FontWeight.bold:FontWeight.normal))));}
Widget _line(Map r,VoidCallback onTap){final name=(r['label']??r['name']??r['account_name']??r['section']??'').toString();final kind=(r['row_type']??r['type']??'').toString().toLowerCase();final bold=kind.contains('total')||name.toLowerCase().contains('total')||kind.contains('section');return TextButton(onPressed:(r['account_id']??r['id'])!=null||name.toLowerCase().contains('current period profit')?onTap:null,child:Text(name.isEmpty?'-':name,style:TextStyle(fontWeight:bold?FontWeight.bold:FontWeight.normal)));}
Widget _moneyOrDash(Object? v)=>Text(toCents(v)==0?'—':formatCurrency(v),textAlign:TextAlign.right,style:const TextStyle(fontFeatures:[FontFeature.tabularFigures()]));String _pct(Object? v){final s=v?.toString()??'';final n=num.tryParse(s);if(n==null||!n.isFinite)return '—';return '${n.toStringAsFixed(2)}%';}
Widget _reportTable(List<String> h,List<List<dynamic>> r)=>SingleChildScrollView(scrollDirection:Axis.horizontal,child:DataTable(columns:h.map((x)=>DataColumn(numeric:x.contains('Period')||x.contains('Date')||x.contains('Debit')||x.contains('Credit')||x.contains('Variance'),label:Text(x,style:const TextStyle(fontWeight:FontWeight.bold)))).toList(),rows:r.map((row)=>DataRow(cells:row.map((v)=>DataCell(v is Widget?v:Text(v.toString()))).toList())).toList()));
Widget _printHeader(String title,String period,Map d)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('GROW Microfinance',style:TextStyle(fontWeight:FontWeight.bold)),Text(title,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Text(period),Text('Generated: ${d['generated_at']??DateTime.now().toIso8601String()}')]);
class _ReportScaffold extends StatelessWidget{const _ReportScaffold({required this.title,required this.subtitle,this.loading=false,this.error,this.filters,required this.children,this.actions=const[]});final String title,subtitle;final bool loading;final String? error;final Widget? filters;final List<Widget> children,actions;@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(c).textTheme.headlineSmall),Text(subtitle)])),...actions]),if(filters!=null)filters!,if(loading)const LinearProgressIndicator(),if(error!=null)_ErrorBox(error!),...children.map((w)=>Padding(padding:const EdgeInsets.symmetric(vertical:6),child:w))]);}
Future<void> _showDrill(BuildContext context,AccountingService service,void Function(String,{String? id}) open,Map account,Map<String,dynamic?> base) async{final id=(account['account_id']??account['id'])?.toString();if(id==null||id.isEmpty)return;await showDialog(context:context,builder:(c)=>_DrillDialog(service:service,open:open,accountId:id,base:base,title:'${account['account_code']??account['code']??''} — ${account['account_name']??account['name']??''}'));}
class _DrillDialog extends StatefulWidget{const _DrillDialog({required this.service,required this.open,required this.accountId,required this.base,required this.title});final AccountingService service;final void Function(String,{String? id}) open;final String accountId,title;final Map<String,dynamic?> base;@override State<_DrillDialog> createState()=>_DrillDialogState();}
class _DrillDialogState extends State<_DrillDialog>{Map<String,dynamic>? data;bool loading=true;String? error;int page=1;@override void initState(){super.initState();load();}Future<void>load()async{setState(()=>loading=true);try{data=await widget.service.accountDrilldown({...widget.base,'account_id':widget.accountId,'page':page});error=null;}catch(e){error=_clean(e);}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext c){final d=data??{};final tx=_list(d,['transactions','items','data']);final s=(d['summary']??d['account']??{}) as Map? ?? {};return AlertDialog(title:Text(widget.title),content:SizedBox(width:1000,child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(loading)const LinearProgressIndicator(),if(error!=null)_ErrorBox(error!),Wrap(spacing:18,runSpacing:8,children:['account_type','account_subtype','normal_balance','opening_balance','total_debit','total_credit','closing_balance'].map((k)=>Text('${_human(k)}: ${k.contains('balance')||k.contains('total')?formatCurrency(s[k]??d[k]):(s[k]??d[k]??'-')}')).toList()),const SizedBox(height:12),_reportTable(['Date','Journal No.','Description','Reference Type','Customer','Loan','Debit','Credit','Running Balance'],tx.map((r)=>[r['date']??'',TextButton(onPressed:()=>widget.open('journalDetail',id:r['journal_id']?.toString()),child:Text(r['journal_no']?.toString()??'')),r['description']??'',humanReferenceType(r['reference_type']?.toString()??''),_linkLabel(_customerLabel(r),r['customer_id']?.toString(),(id)=>widget.open('customers',id:id)),_linkLabel((r['loan_number']??r['loan']??'').toString(),r['loan_id']?.toString(),(id)=>widget.open('loans',id:id)),_moneyOrDash(r['debit']),_moneyOrDash(r['credit']),_moneyOrDash(r['running_balance'])]).toList()),Wrap(children:[TextButton(onPressed:page>1?(){page--;load();}:null,child:const Text('Previous')),Text('Page $page'),TextButton(onPressed:(){page++;load();},child:const Text('Next')),OutlinedButton(onPressed:()=>widget.open('ledger',id:widget.accountId),child:const Text('Open Full General Ledger'))])]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]);}}
